# Generated by manage.py generate_test_cases.
from uuid import uuid4
from datetime import timedelta

from django.utils import timezone

from bloomerp.models.communication.conferencing import ConferenceSession
from bloomerp.models.communication.calendar import CalendarEvent
from bloomerp.services.calendar_conferencing import reserve_calendar_conference
from bloomerp.tests.base import (
    BloomerpModelViewTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.tests.communication.conferencing.sharing_fixtures import SharingFixtures


class TestMeetingView(SharingFixtures, BloomerpModelViewTestCase):
    view_name = "meeting"
    model = ConferenceSession

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Show the minimal public lobby without exposing chat messages or tokens."""
        return [
            RequestScenario(name="Reserved calendar meeting offers its host a start button", user=self.normal_user,
                prepare=self.prepare_reserved, expected=ExpectedResult(response_validators=[
                    self.contains_text("Start meeting"), self.contains_text('data-call-action="join"'),
                    self.does_not_contain_text("This call has ended"), self.does_not_contain_text("data-meeting-request")])),
            RequestScenario(name="Reserved calendar meeting keeps anonymous visitors in the lobby",
                prepare=self.prepare_reserved, expected=ExpectedResult(response_validators=[
                    self.contains_text("data-meeting-request"), self.does_not_contain_text("This call has ended")])),
            RequestScenario(name="Ended calendar meeting does not offer its host a direct join", user=self.normal_user,
                prepare=self.prepare_ended_reserved, expected=ExpectedResult(response_validators=[
                    self.contains_text("This call has ended"), self.does_not_contain_text("data-call-action"),
                    self.does_not_contain_text("data-meeting-request")])),
            RequestScenario(name="Anonymous lobby asks for name", prepare=self.prepare_link, expected=ExpectedResult(response_validators=[self.contains_text('name="name"'), self.does_not_contain_text('Team call')])),
            RequestScenario(name="Authenticated lobby uses account", user=self.admin_user, prepare=self.prepare_link, expected=ExpectedResult(response_validators=self.does_not_contain_text('name="name"'))),
            RequestScenario(name="Unknown token stays hidden", view_kwargs={"token": uuid4()}, expected=ExpectedResult(status_code=404)),
            RequestScenario(name="Archived meeting stays hidden", prepare=self.prepare_archived, expected=ExpectedResult(status_code=404)),
            RequestScenario(name="Ended meeting has a private terminal notice", prepare=self.prepare_ended, expected=ExpectedResult(response_validators=[self.contains_text("This call has ended"), self.does_not_contain_text("data-call-action"), self.does_not_contain_text("data-meeting-request"), self.header_equals("Referrer-Policy", "no-referrer"), self.header_equals("X-Robots-Tag", "noindex, nofollow")])),
        ]

    def prepare_reserved(self, scenario: RequestScenario) -> None:
        """Reserve a calendar meeting without provisioning a live media room."""
        self.prepare_call()
        start = timezone.now()
        event = CalendarEvent.objects.create(
            title="Reserved calendar meeting", organizer_email="host@example.com",
            start=start, end=start + timedelta(hours=1), event_timezone="UTC",
        )
        reserve_calendar_conference(event, self.normal_user, [], "https://testserver/")
        self.session = event.conference_session
        scenario.view_kwargs = {"token": self.session.share_token}

    def prepare_ended_reserved(self, scenario: RequestScenario) -> None:
        """Close a calendar occurrence before its host reopens the shared link."""
        self.prepare_reserved(scenario)
        self.session.status = "ended"
        self.session.started_at = self.session.ended_at = timezone.now()
        self.session.save()

    def prepare_ended(self, scenario: RequestScenario) -> None:
        """Present an ended occurrence without admitting another visitor."""
        self.prepare_link(scenario)
        self.session.status = "ended"
        self.session.started_at = self.session.ended_at = timezone.now()
        self.session.save()

    def prepare_archived(self, scenario: RequestScenario) -> None:
        """Keep archive revocation effective even for known ended links."""
        self.prepare_ended(scenario)
        self.session.room.archived = True
        self.session.room.save()
